/*
 * A259166  Positive heptagonal numbers (A000566) that are hexagonal numbers
 *          (A000384) divided by 2.
 * https://oeis.org/A259166
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   * a(n) = n*(5n-3)/2 where n is obtained from the Pell recurrence
 *            * X^2 - 10Y^2 = 26 with X = 20n - 6, Y = 4m - 1. * The sequence
 *            of (X,Y) is generated by * (X_{k+1}, Y_{k+1}) = (721*X_k +
 *            2280*Y_k, * 721*Y_k + 228*X_k), * starting from (X_0, Y_0) =
 *            (174, 55). The n-th term a(n) is * returned for...
 * Range:     u8 n <= 1, u16 n <= 1, u32 n <= 2, u64 n <= 3, u128 n <= 6,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    /* constants for the recurrence */
    const seq_t U = 721;      /* 721 = 19^2 + 10*6^2 */
    const seq_t V = 228;      /* 228 = 2*19*6    */
    const seq_t C = 2280;     /* C = 10*V        */

    /* starting solution (X_0, Y_0) corresponding to a(1) = 189 */
    seq_t X = 174;           /* X = 20*n - 6   (n = 9)  */
    seq_t Y = 55;            /* Y = 4*m - 1   (m = 14) */

    /* iterate until the n-th term */
    for (idx_t i = 1; i < n; ++i) {
        seq_t newX = U * X + C * Y;
        seq_t newY = U * Y + V * X;
        X = newX;
        Y = newY;
    }

    /* recover n from X and compute a(n) */
    seq_t n_val = (X + 6) / 20;          /* n = (X + 6) / 20 */
    seq_t a_val = n_val * (5 * n_val - 3) / 2;

    return a_val;
}
